export const ORDER_STRINGS = S;

/** A supported locale from ?lang=, else the best Accept-Language match, else 'en'. */
export function pickOrderLang(queryLang, acceptLanguage) {
  const q = String(queryLang || '').toLowerCase().slice(0, 2);
  if (ORDER_LOCALES.includes(q)) return q;
  for (const part of String(acceptLanguage || '').split(',')) {
    const code = part.trim().slice(0, 2).toLowerCase();
    if (ORDER_LOCALES.includes(code)) return code;
  }
  return 'en';
}

/** Translate key into lang; vars are inserted verbatim (callers pass escaped HTML). */
export function ot(lang, key, vars = {}) {
  const table = S[lang] || S.en;
  const text = table[key] ?? S.en[key] ?? key;
  return text.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
}
